using System.Text.Json;
using System.Text.RegularExpressions;
public record TvApp(string Id,string Name,string Icon="");
public record Control(string Action,string Label,int X,int Y,int W,int H,string Id="");
public class Preferences {
 public List<string> Order {get;set;}=new();
 public List<string> Favorites {get;set;}=new();
 public int Wallpaper {get;set;}
}
public class State {
 public List<TvApp> Apps; public Preferences Prefs; readonly string ownAppId; public string Screen="Home";public int Focus=3,Page,Pending=-1;public bool ExitPrompt;public string Message="";
 public State(List<TvApp> apps,Preferences prefs,string ownAppId,bool iptvEnabled){this.ownAppId=ownAppId;Apps=apps.Where(a=>a!=null&&a.Id!=null&&Regex.IsMatch(a.Id,@"^[a-zA-Z0-9_.-]{1,160}$")&&(iptvEnabled||a.Id!=HostConfig.IptvAppId)).DistinctBy(a=>a.Id).ToList();Prefs=prefs;Prefs.Order=Prefs.Order.Where(id=>Apps.Any(a=>a.Id==id)).Distinct().ToList();Prefs.Order.AddRange(Apps.Select(a=>a.Id).Where(id=>!Prefs.Order.Contains(id)));Prefs.Favorites=Prefs.Favorites.Where(id=>Apps.Any(a=>a.Id==id)).Distinct().ToList();Prefs.Wallpaper=Math.Clamp(Prefs.Wallpaper,0,2);}
 public static bool ObservedHome(int homeKey,int code)=>homeKey>0&&code==homeKey;
 public List<TvApp> Ordered()=>Prefs.Order.Select(id=>Apps.First(a=>a.Id==id)).ToList();
 public static string LaunchId(string id)=>id=="com.samsung.tv.store"?"org.volt.apps":id;
 public static string[] StoreStopTargets(string id)=>id=="com.samsung.tv.store"?new[]{"org.volt.apps","com.samsung.tv.store"}:Array.Empty<string>();
 public static string RuntimeId(string id)=>id=="9Ur5IzDKqV.TizenYouTube"?"com.samsung.tv.cobalt-yt":id=="com.samsung.tv.store"?"org.volt.apps":id;
 public static bool PresentationMatches(string target,string full,string partial){target=RuntimeId(target);return target!=""&&(target==full||target==partial);}
 public string PreviousToClose(string target,string foreground,string lastOrdinary=""){string previous=foreground==ownAppId?lastOrdinary:foreground;return previous!=""&&previous!=RuntimeId(target)&&Apps.Any(a=>RuntimeId(a.Id)==previous)?previous:"";}
 public List<Control> Controls(){
  if(ExitPrompt)return new(){new("Cancel","Keep watching",600,490,340,100),new("Exit","Close dashboard",980,490,340,100)};
  var c=new List<Control>{new("Home","Home",350,55,125,58),new("Apps","Apps",510,55,125,58),new("Settings","Settings",670,55,190,58)};
  if(Screen=="Home"){
   var top=Ordered().Take(5).ToList();for(int i=0;i<top.Count;i++)c.Add(new("Launch",top[i].Name,90+i*354,365,326,218,top[i].Id));
   c.AddRange(new[]{new Control("Apps","All apps",90,780,414,126),new("Launch","Picture & sound",533,780,414,126,"com.samsung.tv.quicksetting"),new("Launch","Inputs",976,780,414,126,"quiet.inputs"),new("Launch","App store",1419,780,414,126,"com.samsung.tv.store")});
  }else if(Screen=="Settings"){
   c.AddRange(new[]{new Control("Wallpaper","Wallpaper  ·  "+new[]{"Graphite","Onyx","Smoke"}[Prefs.Wallpaper],100,300,800,90),new("Launch","TV picture & sound",990,300,800,90,"com.samsung.tv.quicksetting"),new("Favorites","Edit favorites",100,430,800,90),new("Launch","Inputs & HDMI",990,430,800,90,"quiet.inputs"),new("Arrange","Arrange apps",100,560,800,90),new("Launch","Install / manage apps",990,560,800,90,"com.samsung.tv.store"),new("Home","Return to Home",100,690,800,90),new("Prompt","Close dashboard",990,690,800,90)});
  }else{
   var all=Ordered();for(int i=Page*10;i<Math.Min(all.Count,(Page+1)*10);i++){int n=i%10;var a=all[i];c.Add(new(Screen=="Favorites"?"Favorite":Screen=="Arrange"?"Swap":"Launch",a.Name,90+n%5*354,300+n/5*290,326,210,a.Id));}
   if(Page>0)c.Add(new("Previous","Previous page",90,920,310,66));if((Page+1)*10<all.Count)c.Add(new("Next","Next page",1520,920,310,66));
  }return c;
 }
 public void Move(string direction){var c=Controls();Focus=Math.Clamp(Focus,0,c.Count-1);var a=c[Focus];double ax=a.X+a.W/2.0,ay=a.Y+a.H/2.0,best=double.MaxValue;int target=Focus;
  for(int i=0;i<c.Count;i++){if(i==Focus)continue;double dx=c[i].X+c[i].W/2.0-ax,dy=c[i].Y+c[i].H/2.0-ay;double primary=direction=="Left"?-dx:direction=="Right"?dx:direction=="Up"?-dy:dy;double cross=direction is "Left" or "Right"?Math.Abs(dy):Math.Abs(dx);if(primary<=0||cross>primary*2.0)continue;double score=primary+cross*3;if(score<best){best=score;target=i;}}
  Focus=target;
 }
 public void Open(string screen){Screen=screen;Page=0;Pending=-1;Focus=3;Message="";}
 public void Back(){if(ExitPrompt){ExitPrompt=false;Focus=3;}else if(Screen=="Home"){ExitPrompt=true;Focus=0;}else Open("Home");}
 public string Select(){var c=Controls();Focus=Math.Clamp(Focus,0,c.Count-1);var item=c[Focus];Message="";
  switch(item.Action){case "Launch":return item.Id;case "Exit":return "@exit";case "Prompt":ExitPrompt=true;Focus=0;break;case "Cancel":ExitPrompt=false;Focus=3;break;case "Home":case "Apps":case "Settings":case "Favorites":case "Arrange":Open(item.Action);break;case "Wallpaper":Prefs.Wallpaper=(Prefs.Wallpaper+1)%3;break;case "Favorite":if(!Prefs.Favorites.Remove(item.Id))Prefs.Favorites.Add(item.Id);break;case "Swap":int i=Prefs.Order.IndexOf(item.Id);if(Pending<0){Pending=i;Message="Choose the app to swap with. Back leaves this screen.";}else{(Prefs.Order[Pending],Prefs.Order[i])=(Prefs.Order[i],Prefs.Order[Pending]);Pending=-1;Message="App order saved.";}break;case "Next":Page++;Focus=3;break;case "Previous":Page--;Focus=3;break;}return "";
 }
 public static void Tests(){
  var apps=new List<TvApp>{new("org.tizen.netflix-app","Netflix"),new("9Ur5IzDKqV.TizenYouTube","YouTube"),new("org.tizen.primevideo","Prime Video"),new("EYm8vc1St4.Philo","Philo"),new("bad;id","unsafe")};const string own="TestPkg001.QuietTV";var s=new State(apps,new Preferences(),own,false);int count=0;void Check(bool ok,string claim){if(!ok)throw new Exception(claim);count++;}
  Check(ObservedHome(63,63)&&!ObservedHome(63,28)&&!ObservedHome(0,0),"observer matches only the configured Home key");Check(s.Prefs.Favorites.Count==0,"no built-in owner favorites");Check(s.Apps.Count==4,"unsafe IDs excluded");s.Move("Right");Check(s.Focus==4,"right selects YouTube");s.Move("Left");Check(s.Focus==3,"left restores Netflix");Check(s.Select()=="org.tizen.netflix-app","launch uses actual enumerated ID");s.Back();Check(s.ExitPrompt&&s.Focus==0,"Back asks to exit with cancel selected");s.Select();Check(!s.ExitPrompt,"OK cancels exit");s.Open("Settings");s.Select();Check(s.Prefs.Wallpaper==1,"wallpaper changes");s.Back();Check(s.Screen=="Home","Back returns Home");s.Open("Favorites");s.Select();Check(s.Prefs.Favorites.Contains("org.tizen.netflix-app"),"favorite added");s.Select();Check(!s.Prefs.Favorites.Contains("org.tizen.netflix-app"),"favorite removed");s.Open("Arrange");s.Select();s.Move("Right");s.Select();Check(s.Prefs.Order[0]=="9Ur5IzDKqV.TizenYouTube","order swapped");s.Open("Apps");for(int i=0;i<40;i++)s.Move("Right");Check(s.Focus<s.Controls().Count,"navigation stays in range");s=new State(apps,new Preferences{Order=new(){"unknown","org.tizen.netflix-app","org.tizen.netflix-app"},Wallpaper=99},own,false);Check(s.Prefs.Order.Count==4&&s.Prefs.Wallpaper==2,"invalid saved settings normalized");Check(PresentationMatches("netflix","netflix",""),"accept foreground app");Check(!PresentationMatches("netflix","com.samsung.tv.csfs",""),"reject Samsung Home handoff");Check(PresentationMatches("settings","com.samsung.tv.csfs","settings"),"accept partial settings window");Check(PresentationMatches("9Ur5IzDKqV.TizenYouTube","com.samsung.tv.cobalt-yt",""),"accept measured YouTube native foreground ID");Check(!PresentationMatches("9Ur5IzDKqV.TizenYouTube","org.tizen.netflix-app",""),"YouTube never accepts Netflix foreground");Check(s.PreviousToClose("org.tizen.primevideo","EYm8vc1St4.Philo")=="EYm8vc1St4.Philo","switching away closes Philo");Check(s.PreviousToClose("org.tizen.netflix-app","com.samsung.tv.cobalt-yt")=="com.samsung.tv.cobalt-yt","close actual YouTube process");Check(s.PreviousToClose("org.tizen.netflix-app","org.tizen.netflix-app")=="","same app kept open");Check(s.PreviousToClose("org.tizen.netflix-app","com.samsung.tv.csfs")=="","never terminate Samsung system Home during app switch");Check(s.PreviousToClose("org.tizen.netflix-app","org.tizen.tv-viewer")=="","never terminate TV input service");Check(s.PreviousToClose("org.tizen.primevideo",own,"EYm8vc1St4.Philo")=="EYm8vc1St4.Philo","remember previous app after registered Home");Check(s.PreviousToClose("org.tizen.netflix-app",own,"org.tizen.netflix-app")=="","resuming same app keeps it alive");Check(State.LaunchId("com.samsung.tv.store")=="org.volt.apps","Store logical ID launches org.volt.apps");Check(PresentationMatches("com.samsung.tv.store","org.volt.apps",""),"Store request accepts observed org.volt.apps foreground");Check(!PresentationMatches("com.samsung.tv.store","com.samsung.tv.store",""),"Store request rejects blank logical Store foreground");Check(!PresentationMatches("com.samsung.tv.store","org.tizen.netflix-app",""),"Store request rejects wrong app");Check(State.LaunchId("9Ur5IzDKqV.TizenYouTube")=="9Ur5IzDKqV.TizenYouTube"&&State.LaunchId("org.tizen.netflix-app")=="org.tizen.netflix-app","YouTube and Netflix launch IDs unchanged");Check(!PresentationMatches("org.tizen.netflix-app","org.volt.apps",""),"Netflix never accepts Store foreground");Check(State.StoreStopTargets("com.samsung.tv.store").SequenceEqual(new[]{"org.volt.apps","com.samsung.tv.store"}),"Store launch stops both registered Store IDs first");Check(State.StoreStopTargets("org.tizen.netflix-app").Length==0&&State.StoreStopTargets("9Ur5IzDKqV.TizenYouTube").Length==0&&State.StoreStopTargets("com.samsung.tv.quicksetting").Length==0&&State.StoreStopTargets("quiet.iptv").Length==0,"other launches stop nothing extra");var withIptv=new List<TvApp>(apps){new("quiet.iptv","IPTV")};Check(!new State(withIptv,new Preferences(),own,false).Apps.Any(a=>a.Id=="quiet.iptv"),"IPTV hidden from the catalogue when disabled");Check(new State(withIptv,new Preferences(),own,true).Apps.Any(a=>a.Id=="quiet.iptv"),"IPTV listed when enabled");Console.WriteLine($"PASS {count} state assertions");
 }
}
